  const dispatch = (type, touches) => page.evaluate((t, ts) => {
    const el = document.querySelector('canvas');
    const tList = ts.map(({ id, x, y }) => ({ identifier: id, clientX: x, clientY: y, pageX: x, pageY: y, target: el }));
    const cList = ts.map(({ id, x, y }) => ({ identifier: id, clientX: x, clientY: y, pageX: x, pageY: y, target: el }));
