  await dispatch('touchmove', [{ id: 1, x: 100, y: 422 }, { id: 2, x: 290, y: 422 }]);
  await page.waitForTimeout(100);
  await dispatch('touchend', [{ id: 1, x: 100, y: 422 }, { id: 2, x: 290, y: 422 }]);
  await page.waitForTimeout(400);

  await page.screenshot({ path: `${OUT}/mobile.png`, fullPage: false });
