import pkg from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pkg;
import { writeFileSync } from 'node:fs';

const OUT = '/tmp/opencode';
const errors = [];
const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: false,
  env: { DISPLAY: ':0' },
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('Failed to load resource')) errors.push('console: ' + m.text()); });

const saveJpg = (name) => page.evaluate(() => {
  const el = document.querySelector('canvas');
  return el.toDataURL('image/jpeg', 0.85);
}).then(data => {
  const b64 = data.split(',')[1];
  writeFileSync(`${OUT}/${name}.jpg`, Buffer.from(b64, 'base64'));
});

const dispatch = (type, touches) => page.evaluate(({ t, ts }) => {
  const el = document.querySelector('canvas');
  const mk = ({ id, x, y }) => ({
    identifier: id, target: el, clientX: x, clientY: y, pageX: x, pageY: y,
    screenX: x, screenY: y, radiusX: 1, radiusY: 1, rotationAngle: 0,
    force: 1, altitudeAngle: 0, azimuthAngle: 0,
  });
  const tList = ts.map(m => new Touch(mk(m)));
  const cList = ts.map(m => new Touch(mk(m)));
  el.dispatchEvent(new TouchEvent(t, {
    touches: tList, targetTouches: tList, changedTouches: cList,
    cancelable: true, bubbles: true,
  }));
}, { t: type, ts: touches });
const wait = ms => new Promise(r => setTimeout(r, ms));

// --- desktop ---
await page.goto('http://localhost:3002/habitat.html', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1500);
await saveJpg('desktop');

// --- mobile + first-person floating gestures ---
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(400);
await dispatch('touchstart', [{ id: 1, x: 195, y: 422 }]);
await wait(100);
await dispatch('touchmove', [{ id: 1, x: 255, y: 372 }]);
await wait(100);
await dispatch('touchend', [{ id: 1, x: 255, y: 372 }]);
await wait(300);
await dispatch('touchstart', [{ id: 1, x: 195, y: 422 }]);
await wait(100);
await dispatch('touchend', [{ id: 1, x: 195, y: 422 }]);
await wait(400);
await dispatch('touchstart', [{ id: 1, x: 130, y: 422 }, { id: 2, x: 260, y: 422 }]);
await wait(100);
await dispatch('touchmove', [{ id: 1, x: 100, y: 422 }, { id: 2, x: 290, y: 422 }]);
await wait(100);
await dispatch('touchend', [{ id: 1, x: 100, y: 422 }, { id: 2, x: 290, y: 422 }]);
await wait(400);
await saveJpg('mobile');

await page.close();
await browser.close();
if (errors.length) { console.log('ERRORS:', errors.join('; ')); process.exitCode = 1; }
else { console.log('wrote desktop.jpg and mobile.jpg, no errors'); }
